    'IsActual' => '1',
    'Snapshot' => 'a:1:{s:10:"Message250";a:1:{i:2;a:25:{s:10:"Message_ID";s:1:"2";s:7:"User_ID";s:1:"1";s:14:"Subdivision_ID";s:1:"5";s:12:"Sub_Class_ID";s:3:"203";s:8:"Priority";s:1:"2";s:7:"Keyword";s:0:"";s:7:"ncTitle";s:0:"";s:10:"ncKeywords";s:0:"";s:13:"ncDescription";s:0:"";s:11:"ncSMO_Title";s:0:"";s:17:"ncSMO_Description";s:0:"";s:11:"ncSMO_Image";N;s:14:"ncFullPageMode";s:7:"inherit";s:17:"ncFullPageCreated";s:1:"0";s:13:"ncDemoContent";s:1:"0";s:7:"Checked";s:1:"1";s:2:"IP";s:14:"193.233.129.42";s:17:"Parent_Message_ID";s:1:"0";s:7:"Created";s:19:"2026-10-14 01:31:40";s:11:"LastUpdated";s:19:"2026-10-14 01:31:40";s:11:"LastUser_ID";s:1:"0";s:6:"LastIP";N;s:4:"text";s:1348:"<p>Зависимость влияет не только на самого человека, но и на его близких. Родственники могут годами пытаться контролировать употребление, убеждать пациента обратиться к врачу или самостоятельно справляться с последствиями очередного срыва.</p>
<p>Специалисты клиники помогают близким понять, как правильно действовать в конкретной ситуации, какие признаки требуют медицинского вмешательства и как разговаривать с человеком о необходимости лечения.</p>
<p>При этом решение о терапии должно приниматься с учётом состояния пациента, медицинских показаний и требований законодательства. Давление и конфликт не всегда помогают сформировать устойчивую мотивацию, поэтому взаимодействие с зависимым человеком требует взвешенного подхода.</p>";s:9:"maintitle";s:56:"Помощь родственникам пациента";s:3:"img";s:33:"trust-family.jpg:image/jpeg:76692";}}}',
  ),
  52 => 
  array (
    'Version_ID' => '553',
    'Version_Changeset_ID' => '2',
